// Preparar datos del guion para generacion de voz
const item = $input.first();
const fields = item.json.fields || item.json;

const guionId = item.json.id || 'ID_DESCONOCIDO';
const cuerpo = fields.cuerpo || '';
const hook = fields.hook || '';
const cta = fields.cta || '';

// Construir texto completo del guion (hook + cuerpo + cta)
const textoCompleto = [hook, cuerpo, cta]
  .filter(t => t && t.trim())
  .join(' ')
  .trim();

// Limpiar texto: quitar indicaciones de produccion en parentesis o corchetes
const textoLimpio = textoCompleto
  .replace(/\([^)]*\)/g, '') // Eliminar (indicaciones entre parentesis)
  .replace(/\[[^\]]*\]/g, '') // Eliminar [indicaciones entre corchetes]
  .replace(/[A-Z]{5,}/g, match => match.toLowerCase()) // Bajar mayusculas de enfasis
  .replace(/\s+/g, ' ')
  .trim();

// Seleccionar voz segun el pilar del contenido
const pilar = fields.pilar || 'Herramientas';
let voiceId;
switch (pilar) {
  case 'Comunidad':
  case 'COMUNIDAD':
    voiceId = process.env.ELEVENLABS_VOICE_ID_CALIDA || $env.ELEVENLABS_VOICE_ID_CALIDA;
    break;
  case 'Ciencia':
  case 'CIENCIA':
    voiceId = process.env.ELEVENLABS_VOICE_ID_PROFESIONAL || $env.ELEVENLABS_VOICE_ID_PROFESIONAL;
    break;
  default:
    voiceId = process.env.ELEVENLABS_VOICE_ID_DEFAULT || $env.ELEVENLABS_VOICE_ID_DEFAULT || 'pNInz6obpgDQGcFmaJgB';
}

if (!textoLimpio || textoLimpio.length < 10) {
  throw new Error(`El guion ${guionId} tiene texto insuficiente para generar voz`);
}

return [{
  json: {
    guion_id: guionId,
    texto_completo: textoLimpio,
    texto_longitud: textoLimpio.length,
    voice_id: voiceId,
    titulo_guion: fields.titulo_guion || 'Sin titulo',
    variacion: fields.variacion || 'PRINCIPAL',
    formato: fields.formato || 'Video corto',
    pilar: pilar,
    idea_id: fields.idea_id || '',
    campos_originales: fields
  }
}];

// Verificar que la respuesta de ElevenLabs contiene audio binario
const response = $input.first();

// El audio viene como datos binarios en $input.first().binary
if (!response.binary || !response.binary.data) {
  // Intentar verificar si viene en el body
  if (!response.json) {
    throw new Error('ElevenLabs no devolvio datos de audio. Verificar API key y voice_id.');
  }
}

const contexto = $('Code: Preparar Texto para Voz').first().json;
const timestamp = new Date().getTime();
const nombreArchivo = `noa_voz_${contexto.guion_id}_${timestamp}.mp3`;

return [{
  json: {
    guion_id: contexto.guion_id,
    titulo_guion: contexto.titulo_guion,
    variacion: contexto.variacion,
    formato: contexto.formato,
    pilar: contexto.pilar,
    idea_id: contexto.idea_id,
    nombre_archivo_audio: nombreArchivo,
    texto_completo: contexto.texto_completo,
    texto_longitud: contexto.texto_longitud,
    campos_originales: contexto.campos_originales
  },
  binary: response.binary
}];

// Guardar URL del audio y preparar para timestamps
const driveResponse = $input.first();
const audioContext = $('Code: Verificar y Preparar Audio').first().json;

const audioFileId = driveResponse.json.id || driveResponse.json.fileId;
const audioUrl = `https://drive.google.com/uc?id=${audioFileId}&export=download`;
const audioWebViewUrl = `https://drive.google.com/file/d/${audioFileId}/view`;

return [{
  json: {
    guion_id: audioContext.guion_id,
    titulo_guion: audioContext.titulo_guion,
    variacion: audioContext.variacion,
    formato: audioContext.formato,
    pilar: audioContext.pilar,
    idea_id: audioContext.idea_id,
    nombre_archivo_audio: audioContext.nombre_archivo_audio,
    audio_file_id: audioFileId,
    audio_url: audioUrl,
    audio_web_view_url: audioWebViewUrl,
    texto_completo: audioContext.texto_completo,
    texto_longitud: audioContext.texto_longitud,
    campos_originales: audioContext.campos_originales
  }
}];

// Generar archivo SRT desde timestamps de ElevenLabs
const timestampsData = $input.first().json;
const audioContext = $('Code: Guardar URL del Audio').first().json;

const alignment = timestampsData.alignment || {};
const characters = alignment.characters || [];
const charStartTimes = alignment.character_start_times_seconds || [];
const charEndTimes = alignment.character_end_times_seconds || [];

if (characters.length === 0) {
  throw new Error('No hay datos de caracteres en el alignment de ElevenLabs');
}

// Reconstruir palabras con sus tiempos
const palabras = [];
let palabraActual = '';
let startPalabra = 0;

for (let i = 0; i < characters.length; i++) {
  const char = characters[i];
  if (char === ' ' || char === '\n') {
    if (palabraActual.trim()) {
      palabras.push({
        texto: palabraActual.trim(),
        inicio: startPalabra,
        fin: charEndTimes[i - 1] || charEndTimes[i]
      });
    }
    palabraActual = '';
    startPalabra = charStartTimes[i + 1] || charStartTimes[i];
  } else {
    if (!palabraActual) {
      startPalabra = charStartTimes[i];
    }
    palabraActual += char;
  }
}
// Ultima palabra
if (palabraActual.trim()) {
  palabras.push({
    texto: palabraActual.trim(),
    inicio: startPalabra,
    fin: charEndTimes[charEndTimes.length - 1]
  });
}

// Agrupar palabras en bloques de subtitulo (max 7 palabras o 5 segundos)
const PALABRAS_POR_BLOQUE = 7;
const bloques = [];
for (let i = 0; i < palabras.length; i += PALABRAS_POR_BLOQUE) {
  const grupo = palabras.slice(i, i + PALABRAS_POR_BLOQUE);
  bloques.push({
    numero: bloques.length + 1,
    inicio: grupo[0].inicio,
    fin: grupo[grupo.length - 1].fin,
    texto: grupo.map(p => p.texto).join(' ')
  });
}

// Funcion para formatear tiempo en HH:MM:SS,mmm
const formatSRTTime = (seconds) => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const ms = Math.round((seconds % 1) * 1000);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
};

// Generar contenido SRT
const srtContent = bloques.map(bloque => [
  bloque.numero,
  `${formatSRTTime(bloque.inicio)} --> ${formatSRTTime(bloque.fin)}`,
  bloque.texto,
  ''
].join('\n')).join('\n');

const nombreSRT = `noa_sub_${audioContext.guion_id}_${new Date().getTime()}.srt`;

return [{
  json: {
    guion_id: audioContext.guion_id,
    titulo_guion: audioContext.titulo_guion,
    variacion: audioContext.variacion,
    formato: audioContext.formato,
    pilar: audioContext.pilar,
    idea_id: audioContext.idea_id,
    audio_url: audioContext.audio_url,
    audio_web_view_url: audioContext.audio_web_view_url,
    srt_content: srtContent,
    nombre_archivo_srt: nombreSRT,
    total_bloques_srt: bloques.length,
    total_palabras: palabras.length,
    metodo_srt: 'elevenlabs_timestamps'
  }
}];

// Fallback: Generar SRT estimado cuando no hay timestamps de ElevenLabs
// Estima timing basado en velocidad de habla promedio en espanol: ~150 palabras/min
const audioContext = $('Code: Guardar URL del Audio').first().json;
const textoCompleto = audioContext.texto_completo || '';

const VELOCIDAD_PALABRAS_POR_SEG = 2.5; // ~150 palabras/minuto en espanol
const PALABRAS_POR_BLOQUE = 6;

const palabras = textoCompleto.split(/\s+/).filter(p => p.length > 0);

// Agrupar en bloques
const bloques = [];
let tiempoActual = 0;

for (let i = 0; i < palabras.length; i += PALABRAS_POR_BLOQUE) {
  const grupo = palabras.slice(i, i + PALABRAS_POR_BLOQUE);
  const duracionBloque = grupo.length / VELOCIDAD_PALABRAS_POR_SEG;

  bloques.push({
    numero: bloques.length + 1,
    inicio: tiempoActual,
    fin: tiempoActual + duracionBloque,
    texto: grupo.join(' ')
  });

  tiempoActual += duracionBloque;
}

const formatSRTTime = (seconds) => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const ms = Math.round((seconds % 1) * 1000);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
};

const srtContent = bloques.map(bloque => [
  bloque.numero,
  `${formatSRTTime(bloque.inicio)} --> ${formatSRTTime(bloque.fin)}`,
  bloque.texto,
  ''
].join('\n')).join('\n');

const nombreSRT = `noa_sub_est_${audioContext.guion_id}_${new Date().getTime()}.srt`;

return [{
  json: {
    guion_id: audioContext.guion_id,
    titulo_guion: audioContext.titulo_guion,
    variacion: audioContext.variacion,
    formato: audioContext.formato,
    pilar: audioContext.pilar,
    idea_id: audioContext.idea_id,
    audio_url: audioContext.audio_url,
    audio_web_view_url: audioContext.audio_web_view_url,
    srt_content: srtContent,
    nombre_archivo_srt: nombreSRT,
    total_bloques_srt: bloques.length,
    total_palabras: palabras.length,
    metodo_srt: 'estimacion_velocidad_habla',
    advertencia: 'SRT generado con estimacion. Revisar sincronizacion manualmente.'
  }
}];

// Preparar datos finales para actualizar Airtable
const srtContext = $input.first().json;
const driveResponse = $('Google Drive: Subir Archivo SRT').first().json;

const srtFileId = driveResponse.id || driveResponse.fileId;
const srtUrl = `https://drive.google.com/uc?id=${srtFileId}&export=download`;
const srtWebViewUrl = `https://drive.google.com/file/d/${srtFileId}/view`;

return [{
  json: {
    guion_id: srtContext.guion_id,
    titulo_guion: srtContext.titulo_guion,
    variacion: srtContext.variacion,
    formato: srtContext.formato,
    pilar: srtContext.pilar,
    idea_id: srtContext.idea_id,
    audio_url: srtContext.audio_url,
    audio_web_view_url: srtContext.audio_web_view_url,
    srt_url: srtUrl,
    srt_web_view_url: srtWebViewUrl,
    metodo_srt: srtContext.metodo_srt,
    total_bloques_srt: srtContext.total_bloques_srt,
    advertencia: srtContext.advertencia || null,
    fecha_generacion_voz: new Date().toISOString().split('T')[0]
  }
}];

