const error = $input.first();

const errorInfo = {
  workflow: 'NOA - Voz y Subtitulos',
  timestamp: new Date().toISOString(),
  error_message: error.json.message || error.json.error || JSON.stringify(error.json),
  context: 'Error en pipeline de voz y subtitulos'
};

console.error('Error en workflow Voz:', JSON.stringify(errorInfo));

return [{ json: errorInfo }];
